const tableBytes = Uint8Array.from(atob(encodedTable), char => char.charCodeAt(0));
const b2uTable = new Uint16Array(tableBytes.length / 2);
for (let index = 0; index < b2uTable.length; index++) {
  b2uTable[index] = tableBytes[index * 2] | (tableBytes[index * 2 + 1] << 8);
}

export function decodeUao(lead, trail) {
  if (lead < 0x81 || lead > 0xfe) return null;
  const trailIndex = trail >= 0x40 && trail <= 0x7e ? trail - 0x40
    : trail >= 0xa1 && trail <= 0xfe ? trail - 0xa1 + 63 : -1;
  if (trailIndex < 0) return null;
  const codePoint = b2uTable[(lead - 0x81) * 157 + trailIndex];
  return codePoint && codePoint !== 0xfffd ? String.fromCharCode(codePoint) : null;
}
